(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20 + Math.cos(y*0.013-t*0.18)*15;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.015+t*0.3)*12;
  const wx2 = Math.sin((x+w1x)*0.012+t*0.15)*10 + Math.cos((y+w1y)*0.01-t*0.12)*8;
  const wy2 = Math.cos((y+w1y)*0.014-t*0.17)*10 + Math.sin((x+w1x)*0.011+t*0.2)*8;
  const sx = x+w1x+wx2, sy = y+w1y+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.075,2.1,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.09,1.8,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.055,2.4,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.11,1.6,0.85],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.065,2.7,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.085,2.0,0.95],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+4)*60,0.1,1.4,0.8],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+1)*80,0.07,2.2,1.0]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    aS+=wave*w;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+1.5)*w;
    mS+=Math.sin(d*f*1.3-t*sp*0.8+3.0)*w*0.5;
  }
  const n=8,act=aS/n,inh=iS/n,mod=mS/n;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2
    +Math.sin((sx+sy)*0.1+t*2.2)*0.25+Math.sin((sx-sy)*0.09-t*1.8)*0.25
    +Math.sin(sx*0.06+sy*0.055-t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t*1.0))*0.35
    +Math.sin(dist*0.02-ang*6+t*0.8)*0.15;
  const micro=Math.sin(sx*0.25+t*3)*Math.sin(sy*0.25-t*2.5)*0.12
    +Math.sin((sx-sy)*0.18+t*4)*0.08;
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral+mod*0.3+micro)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.5)*1.4)*0.28;
  const vein=Math.abs(Math.sin(Math.atan2(Math.sin(sy*0.08+t*0.3),Math.sin(sx*0.08-t*0.2))*3+dist*0.03-t))*0.15;
  const pulse=0.95+Math.sin(t*0.8)*0.05+Math.sin(reaction*Math.PI*1.2)*0.12;
  const blend=reaction*0.65+cell*0.2+vein*0.15,v=blend*0.5+0.5;
  const pal=[
    [5,12,45],[12,35,82],[18,72,108],[28,125,128],[55,168,118],
    [135,195,85],[195,195,60],[220,165,65],[210,120,70],[185,75,80],
    [140,40,85],[85,25,72],[40,18,58],[5,12,45]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sharp=Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.05:1.0;
  const glow=Math.max(0,reaction-0.3)*0.4;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*pulse*sharp+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*pulse*sharp+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*pulse*sharp+glow*20)|0)
  ];
}
